package com.gaurav.secretlauncher;
import android.app.*;import android.os.*;import android.content.*;import android.content.pm.*;import android.graphics.Color;import android.graphics.drawable.Drawable;import android.text.InputType;import android.view.*;import android.widget.*;import java.util.*;
public class MainActivity extends Activity {
 SharedPreferences prefs; LinearLayout root; TextView display; String input=""; boolean inVault=false;
 static class App {String pkg,name;Drawable icon;App(String p,String n,Drawable d){pkg=p;name=n;icon=d;}}
 ArrayList<App> apps=new ArrayList<>();
 public void onCreate(Bundle b){super.onCreate(b);prefs=getSharedPreferences("secret",MODE_PRIVATE);load();home();}
 void load(){apps.clear();PackageManager pm=getPackageManager();Intent q=new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_LAUNCHER);HashSet<String> seen=new HashSet<>();for(ResolveInfo r:pm.queryIntentActivities(q,0)){String p=r.activityInfo.packageName;if(!p.equals(getPackageName())&&seen.add(p))apps.add(new App(p,r.loadLabel(pm).toString(),r.loadIcon(pm)));}Collections.sort(apps,(a,b)->a.name.compareToIgnoreCase(b.name));}
 boolean hidden(String p){return prefs.getStringSet("hidden",Collections.emptySet()).contains(p);}
 void toggle(App a){Set<String> s=new HashSet<>(prefs.getStringSet("hidden",Collections.emptySet()));if(!s.add(a.pkg))s.remove(a.pkg);prefs.edit().putStringSet("hidden",s).apply();manage();}
 TextView label(String s,int size){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(Color.WHITE);t.setGravity(Gravity.CENTER);return t;}
 void base(boolean wallpaper){root=new LinearLayout(this);root.setOrientation(1);root.setPadding(12,38,12,12);root.setBackgroundColor(0xff182033);if(wallpaper)try{root.setBackground(android.app.WallpaperManager.getInstance(this).getDrawable());}catch(Exception e){}setContentView(root);}
 void top(String title,Runnable back){LinearLayout row=new LinearLayout(this);root.addView(row);TextView h=label(title,22);row.addView(h,new LinearLayout.LayoutParams(0,58,1));if(back!=null){TextView b=label("✕",24);row.addView(b,new LinearLayout.LayoutParams(55,58));b.setOnClickListener(v->back.run());}}
 void button(String s,Runnable action){TextView t=label(s,18);t.setBackgroundColor(0xff314365);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,55);lp.setMargins(2,5,2,5);root.addView(t,lp);t.setOnClickListener(v->action.run());}
 void listing(boolean showHidden,boolean manage){ScrollView scroll=new ScrollView(this);LinearLayout rows=new LinearLayout(this);rows.setOrientation(1);scroll.addView(rows);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));ArrayList<App> visible=new ArrayList<>();for(App a:apps)if(manage||hidden(a.pkg)==showHidden)visible.add(a);for(int i=0;i<visible.size();i+=4){LinearLayout row=new LinearLayout(this);rows.addView(row);for(int j=0;j<4;j++){if(i+j>=visible.size()){row.addView(new View(this),new LinearLayout.LayoutParams(0,105,1));continue;}App a=visible.get(i+j);LinearLayout cell=new LinearLayout(this);cell.setGravity(Gravity.CENTER);cell.setOrientation(1);ImageView icon=new ImageView(this);icon.setImageDrawable(a.icon);cell.addView(icon,new LinearLayout.LayoutParams(55,55));TextView name=label(a.name,11);name.setSingleLine(true);name.setEllipsize(android.text.TextUtils.TruncateAt.END);cell.addView(name);if(manage){TextView status=label(hidden(a.pkg)?"HIDDEN":"VISIBLE",10);cell.addView(status);}row.addView(cell,new LinearLayout.LayoutParams(0,105,1));cell.setOnClickListener(v->{if(manage)toggle(a);else launch(a);});cell.setOnLongClickListener(v->{if(!manage&&!showHidden)new AlertDialog.Builder(this).setTitle(a.name).setPositiveButton("Hide",(d,w)->{Set<String> s=new HashSet<>(prefs.getStringSet("hidden",Collections.emptySet()));s.add(a.pkg);prefs.edit().putStringSet("hidden",s).apply();home();}).setNegativeButton("Cancel",null).show();return true;});}}}
 void launch(App a){try{Intent i=getPackageManager().getLaunchIntentForPackage(a.pkg);if(i!=null)startActivity(i);}catch(Exception e){Toast.makeText(this,"Cannot open app",0).show();}}
 void home(){inVault=false;base(true);top(" ",null);button("Calculator",()->calculator());button("All Apps",()->drawer());listing(false,false);}
 void drawer(){inVault=false;base(false);top("All Apps",()->home());listing(false,false);}
 void calculator(){inVault=false;input="";base(false);top("Calculator",()->home());display=label("0",38);root.addView(display,new LinearLayout.LayoutParams(-1,0,1));String[][] keys={{"7","8","9"},{"4","5","6"},{"1","2","3"},{"C","0","="}};for(String[] line:keys){LinearLayout row=new LinearLayout(this);root.addView(row,new LinearLayout.LayoutParams(-1,75));for(String k:line){TextView t=label(k,26);t.setBackgroundColor(0xff293d60);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,-1,1);p.setMargins(3,3,3,3);row.addView(t,p);t.setOnClickListener(v->{if(k.equals("C"))input="";else if(k.equals("=")){if(input.equals(prefs.getString("pin","2580"))){secret();return;}else input="";}else if(input.length()<16)input+=k;display.setText(input.isEmpty()?"0":input);});}}}
 void secret(){inVault=true;base(false);top("Hidden Apps",()->home());button("Hide / Unhide Apps",()->manage());button("Change PIN",()->changePin());listing(true,false);}
 void manage(){inVault=true;base(false);top("Select Apps to Hide",()->secret());listing(false,true);}
 void changePin(){EditText e=new EditText(this);e.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_VARIATION_PASSWORD);e.setHint("New 4-8 digit PIN");new AlertDialog.Builder(this).setTitle("Change PIN").setView(e).setNegativeButton("Cancel",null).setPositiveButton("Save",(d,w)->{String s=e.getText().toString();if(s.matches("[0-9]{4,8}"))prefs.edit().putString("pin",s).apply();else Toast.makeText(this,"Use 4-8 digits",0).show();}).show();}
 @Override public void onBackPressed(){home();}
}